ALLOWED = {'images.example.com', 'cdn.example.com'}

@app.get('/preview')
def preview():
    url = request.args['url']
    if urlparse(url).hostname not in ALLOWED:
        abort(400)
    return requests.get(url, timeout=5).text[:500]

